"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def findPairs(arr, target):
    seen = set()
    pairs = []
    for num in arr:
        complement = (target - num)
        if (complement in seen):
            pairs.append((complement, num))
        seen.add(num)
    return pairs
print(findPairs([1, 2, 3, 4, 5], 5))